 for(const s of G.shots){for(const e of G.enemies){if(e.state!=='challenge')continue;if(circleRect(e.x,e.y,7,s.x,s.y,1,4)){s.dead=true;G.stats.hits++;G.challengingHits++;destroyEnemy(e);SFX.destroy();score(100);}}}
 G.shots=G.shots.filter(s=>!s.dead);
